INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000000426', 'radical', '夌', 'frostbite', 52, 0, 'Radikal ini terbuat dari tanah, kaki, dan musim dingin. Jika Anda harus mengubur kaki Anda di tanah pada musim dingin, itu mungkin karena Anda mengalami radang dingin. Anda harus meninggalkan kaki Anda yang mati. :(', NULL, NULL),
  ('00000000-0000-4000-8000-000000000432', 'radical', '胃', 'stomach', 51, 0, 'Radikal ini sama dengan kanji. Artinya perut.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000434', 'radical', '凸', 'convex', 57, 0, 'Ini terlihat seperti sebuah kotak dengan sesuatu yang mencuat di dalamnya. Jika ada sesuatu yang menonjol dari benda lain, maka benda itu cembung.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000435', 'radical', '凹', 'concave', 57, 1, 'Sepertinya ada penyok di kotak ini. Bila ada lubang atau penyok pada suatu benda disebut cekung.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000436', 'radical', '下', 'below', 59, 0, 'Radikal ini sama dengan kanji. Artinya di bawah.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000437', 'radical', '勇', 'courage', 60, 0, 'Radikal ini sama dengan kanji. Artinya keberanian.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000438', 'radical', '高', 'tall', 53, 0, 'Radikal ini sama dengan kanji. Artinya <radikal>tinggi</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000466', 'kanji', '又', '又', 51, 42, 'Kamu duduk di bangkumu lagi!!?', 'Teman-temanmu mulai mengkhawatirkanmu, karena kamu selalu duduk di bangku itu. "Ada apa (また) denganmu?" mereka berteriak! Anda mungkin ingin membayangkan bahwa semua teman Anda memiliki aksen Jamaika dan/atau Inggris agar aksen ini lebih cocok!', NULL),
  ('00000000-0000-4000-8000-000000002120', 'kanji', '偉', '偉', 51, 1, 'The leader of Korea is destined for greatness.', 'The greatness radiates off of the leader of Korea, so much so that you can hardly look. Just when you''re about to close your eyes to shield them from the greatness, a great eagle (い) soars over them, letting out a cry.', NULL),
  ('00000000-0000-4000-8000-000000002121', 'kanji', '頂', '頂', 51, 2, 'Take the street all the way to that geoduck, way up there. When you reach it, you will have made it to the summit. You humbly present the road to the geoduck and bow before it.', 'You are at the top, the summit of everything! You humbly survey your surroundings from the top of the geoduck, only to see someone on the street, running toward you. It is Mrs. Chou (ちょう), and she looks angry.', NULL),
  ('00000000-0000-4000-8000-000000002122', 'kanji', '召', '召', 51, 3, 'The call radical and the call kanji are the same. This kanji can also mean eat, because why would you call someone if not to ask them to eat with you?!', 'You are called to come eat by the Shougun (しょう). He''s been really impressed with you lately and he wants to chat over drinks, he says on the phone.', NULL),
  ('00000000-0000-4000-8000-000000002123', 'kanji', '挟', '挟', 51, 4, 'Your fingers have husband horns. They are there right between each of your fingers.', 'What is between your fingers? Your husband (はさ) horns.', NULL),
  ('00000000-0000-4000-8000-000000002124', 'kanji', '枯', '枯', 51, 5, 'When a tree grows old, it will wither.', 'This withered tree''s best friend is a human 子 (こ). Imagine the child hugging the tree.', NULL),
  ('00000000-0000-4000-8000-000000002125', 'kanji', '沸', '沸', 51, 6, 'If a tsunami hits a dollar the water will instantly start to boil!', 'The boiling water crashes onto the land and you realize your foot is in it! No, not one foot, both your foots (ふつ)! It hurts so much that you can''t even remember the word for two foots.', NULL),
  ('00000000-0000-4000-8000-000000002126', 'kanji', '濯', '濯', 51, 7, 'You need to throw your two wolverines and your turkey into the oncoming tsunami if you want to wash them at the same time. It''s the only way you can get them clean at once without the wolverines fighting over the turkey and somebody getting hurt. The tsunami is big enough to wash them all before anything bad happens.', 'Once they''re nice and washed you need to subdue them by poking each of them with a tack (たく). The tack has special sleeping medicine on it, so once they''re nice and clean you can put them back in their cages without them trying to eat each other.', NULL),
  ('00000000-0000-4000-8000-000000002127', 'kanji', '燥', '燥', 51, 8, 'Put syrup too close to fire and it will dry up. Put any liquid substance near fire and it will dry up actually, but syrup especially. It goes from being sticky and gooey and yummy to a pile of hard, dry sugar. Not so yummy.', 'If you dry up syrup like this, you''re removing its soul (そう). Have you ever seen dry syrup before? No soul in that. In fact, you probably have no soul if you can dry out syrup like this without feeling bad about it.', NULL),
  ('00000000-0000-4000-8000-000000002128', 'kanji', '瓶', '瓶', 51, 9, 'A lantern with horns that can hold ten thousand drops of water is sitting on the ground. You get closer and realize it''s not a lantern, it''s a bottle. It''s got horns, and a weird handle, but it''s definitely a bottle with water inside of it.', 'Even though you''re not the one who left this bottle here, you decide to do the right thing and throw it in the trash bin (びん). It''s not right to leave a bottle just sitting on the ground, you know.', NULL),
  ('00000000-0000-4000-8000-000000002129', 'kanji', '耕', '耕', 51, 10, 'You have a plow and a (water) well. These are the two things you need in order to plow.', 'plowing all the fields are こういちs. Not Emperor こういち. These are the こういち clones the government made, and now they''re being put to use.', NULL),
  ('00000000-0000-4000-8000-000000002130', 'kanji', '肯', '肯', 51, 11, 'We must stop the moon. That, at least, we can come to an agreement on.', '"We have agreement," the world''s leaders all say. "We will work together to stop the moon, and we have agreement on who we will follow, Emperor こういち.', NULL),
  ('00000000-0000-4000-8000-000000002131', 'kanji', '脂', '脂', 51, 12, 'If you eat both the moon and the sun with a spoon you''ll get fat. Maybe if you only ate one you could get away with it, but you wanted both and now you''re pretty fat.', 'Once you''re nice and fat, you look in the mirror to admire your new girth. But that''s not you... it''s a sheep (し)!', NULL),
  ('00000000-0000-4000-8000-000000002132', 'kanji', '膚', '膚', 51, 13, 'If you look in a tiger''s stomach you''ll find a bunch of skin. It''s really gross but what else did you think you''d find? Everyone knows tigers can''t digest the skin of the things it eats.', 'The only person who would try to take skin from a tiger''s stomach is a fool (ふ). You''ll probably get your head bitten off looking for skin that way.', NULL),
  ('00000000-0000-4000-8000-000000002133', 'kanji', '軒', '軒', 51, 14, 'Your car is dry because you kept it under the eaves of your house. 
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000002312', 'kanji', '弦', '弦', 56, 17, 'The mysterious sound that comes from a bowstring when you pluck it is called a chord. It''s still a bowstring though. You need strings to make chords, after all.', 'The chord you''re hearing right now is being played by Genji (げん). He''s sitting under your window plucking bowstrings and singing.', NULL),
  ('00000000-0000-4000-8000-000000002313', 'kanji', '窒', '窒', 56, 18, 'Take a mole out of its hole and it will suffocate. They need to be in tight quarters, unlike us humans. So when you take one out of its nice, safe hole, it thinks it can''t breathe and suffocates.', 'As the mole suffocates it cheats (ちつ) and shoves its head into your closed hand. You realize what it''s doing and squeeze your hand tighter so it''s more like a hole. You can feel the mole breathing again now.', NULL),
  ('00000000-0000-4000-8000-000000002314', 'kanji', '洪', '洪', 56, 19, 'A tsunami together with another tsunami is going to cause a massive flood.', 'After the terrible flood, Emperor こういち comes to survey the destruction and offer hope to his people. But, instead he just tells the people that this flood happened because they didn''t believe in the Crabigator''s words, and because they weren''t doing their kanji reviews.', NULL),
  ('00000000-0000-4000-8000-000000002315', 'kanji', '摂', '摂', 56, 20, 'Put your fingers in your ears when there''s an explosion in addition to all the other things you were told to do. You have to crouch under a desk, you have to stay away from windows, you have to close your eyes. But in addition to that, you need to protect your ears!', 'In addition to all the steps you have to take to protect yourself, you can''t forget that ears come in sets (せつ). You can''t just stick one finger in one ear and have that be the end. You have a set of ears to worry about!', NULL),
  ('00000000-0000-4000-8000-000000002316', 'kanji', '飽', '飽', 56, 21, 'You eat and then wrap yourself into a ball because you''re bored. You''re also sated, because you ate just the right amount, but now you have nothing to do and it''s soooo booooring.', 'So now you''re bored and stuck at home (ほう). You aren''t hungry. There''s nothing on TV. And you don''t want to have to leave your home to do something, even though that would probably solve your boredom problem.', NULL),
  ('00000000-0000-4000-8000-000000002317', 'kanji', '紳', '紳', 56, 22, 'Your threads are humble and that makes you a perfect gentleman. You don''t have to have fancy clothes to be a gentleman, just humble ones that don''t stand out and show off too much. That shows how polite you are.', 'Unfortunately, as a gentleman who dresses humbly, you''re always getting kicked in the shins (しん) by rude kids (and occasionally rude adults).', NULL),
  ('00000000-0000-4000-8000-000000002318', 'kanji', '庸', '庸', 56, 23, 'Under this canopy you have a brush and a task to complete with it. This is totally common.', 'This is so common and familiar to you that you finish your task early and eat some yogurt (よう) while you wait for the guy to come back.', NULL),
  ('00000000-0000-4000-8000-000000002319', 'kanji', '靖', '靖', 56, 24, 'Stand staring up at the blue sky and you''ll feel more peaceful than you ever have. Blue is a color that promotes peaceful thoughts and feelings. That''s why all the social media sites are blue. To stop you from being a jerk.', 'Now if someone asks you if the color blue makes you peaceful you should say "YES! (やす)" And you''ll have us to thank for that! All those peaceful blue radicals. They''re the easiest thing on the site, and if someone asks you if radicals make you feel peaceful say YES again!', NULL),
  ('00000000-0000-4000-8000-000000002320', 'kanji', '嘉', '嘉', 56, 25, 'If when you speak it sounds like the power of a drum is coming out of your mouth, then people will hold you in high esteem. Anyone who has a loud, booming, powerful voice will be held in high esteem in this day and age. Look at all those awesome musicians who have booming voices!', 'You hold them in such high esteem that you give them your car (か). I ... I said you give them your car! Give them your car. Hey, hey!', NULL),
  ('00000000-0000-4000-8000-000000002321', 'kanji', '搾', '搾', 56, 26, 'If you want to fit your fingers into a key hole, you have to squeeze them in. Fingers aren''t exactly supposed to fit in key holes... they''re for keys, after all. But you want to squeeze your finger on in there anyway to unlock the door.', 'Once you''ve squeezed your finger in the key hole to unlock this door you squeeze all the money and jewels and treasures you can fit into your sack (さく). Your stealing sack.', NULL),
  ('00000000-0000-4000-8000-000000002322', 'kanji', '蝶', '蝶', 56, 27, 'The insect that is amongst all the world''s trees is the butterfly. They are always hanging around trees, those butterflies.', 'As you look at a butterfly, fluttering around a tree, a hand reaches out from the tree and grabs it, then starts plucking the wings off. An evil laugh comes from inside the tree, and you know it''s Mrs. Chou (ちょう).', NULL),
  ('00000000-0000-4000-8000-000000002323', 'kanji', '碑', '碑', 56, 28, 'A stone drops from the sky into a rice paddy and then a cross drops on top of it. They''ve combined to form a tombstone! Wait, does that mean a body fell from the sky first and you just didn''t see it?', 'Now you''re curious about what''s under there but when you try to touch the tombstone it''s radiating with intense heat (ひ)! It must have come from outer space and this heat is from when it entered our atmosphere!', NULL),
  ('00000000-0000-4000-8000-000000002324', 'kanji', '尉', '尉', 56, 29, 'Who loves their flag, using jackhammers, and precise measurements? Your military officer! He''s always saluting the flag, jackhammering near all the new recruits to test them, and checking the measurement between the floor and their pants. Who else could it be?', 'That military officer''s favorite bird is an eagle (い)! That should be obvious because the eagle is the bird of America! And that''s the country he fights for!', NULL),
  ('00000000-0000-4000-8000-000000002325', 'kanji', '凛', '凛', 56, 30, 'You''re trying to open the lid of a manhole that''s covered in ice by jackhammering it a bunch of times but it''s not working because it''s just too cold. It''s so cold that your jackhammer is starting to ice up too. But you need to get this lid open so you try time after time after time!', 'Each time the jackhammer hits the freezing cold ice it makes a high pitched ringing (りん) sound. It''s actually really annoying to listen to but you really need to crack this ice open so you have to keep listening to it.', NULL),
  ('00000000-0000-4000-8000-000000002326', 'kanji', '匠', '匠', 56, 31, 'There is a cage with an axe in it above your house to show that you are an artisan. All of the artisans have to have this special sign somewhere near where they live to show they make things.', 'Artisans have to be marked this way because the Shougun (しょう) says so. The Shougun doesn''t want to have to put any effort into finding people to make things for him, so he created this new system.', NULL),
  ('00000000-0000-4000-8000-000000002327', 'kanji', '遥', '遥', 56, 32, 'There is a scooter that is a satellite, but it is far off and far away.', 'The scooter satellite is far off, but you can still hear it''s horn go "har (はる) har har."', NULL),
  ('00000000-0000-4000-8000-000000002328', 'kanji', '智', '智', 56, 33, 'You shoot an arrow at the mouth of the sun so that it will grant you a gift of wisdom. You heard about a Greek hero doing this and the god in the sun gave him the wisdom to see everything. You''re hoping it will work for you too.', 'You''re standing around waiting for the wisdom to hit you when something else does. In the head. Ouch! You look down and it''s a wheel of cheese (ち)! At first you''re angry, until you realize that this must be a sign. Cheese IS wisdom. And the key to wisdom is eating a lot of cheese!', NULL),
  ('00000000-0000-4000-8000-000000002329', 'kanji', '柴', '柴', 56, 34, 'If you could stop spooning water onto that tree we could use it for brushwood. But if you don''t stop, then it will be too wet to burn at all! Stop already!', 'You finally set the brushwood on fire and suddenly a Shiba (しば) Inu jumps out of the flames. So that''s why they named this wood after them or... or vice versa?', NULL),
  ('00000000-0000-4000-8000-000000002330', 'kanji', '賊', '賊', 57, 2, 'When a shellfish becomes a drunkard and sees a cross, they''ll become a robber. Because they''ll steal the cross!', 'Once the shellfish has a taste for being a robber, he''ll join a Bosozoku (ぞく) bike gang so he can keep stealing more and more crosses. He''ll drink more, steal more, and get to ride cool motorcycles.', NULL),
  ('00000000-0000-4000-8000-000000002331', 'kanji', '鼓', '鼓', 57, 3, 'You take a drum and a branch and... well, what else would you do? You would drum or beat them together.', 'Who loves to drum things together and make a huge racket? 子s (こ), of course.', NULL),
  ('00000000-0000-4000-8000-000000002332', 'kanji', '旋', '旋', 57, 4, 'Move your coat rack in one direction by shooting it with a gun. Then you can keep shooting it to get a good rotation going. If you think there is a better way to make your coat rack make revolutions, you''re probably wrong.', 'As you watch your coat rack''s rotations a centaur (せん) barges in and takes the gun from you, stops the rotating coat rack and leaves. How rude! I guess centaurs don''t like when things rotate.', NULL),
  ('00000000-0000-4000-8000-000000002333', 'kanji', '腸', '腸', 57, 5, 'The moon is easy tonight, so you decide to cut it open. But, the moon wasn''t the moon, it was your big, pale, round tummy. You just cut it open, and now you can see your intestines.', 'All over the world, people are cutting their bellies open, because they think its an easy moon (versus a normal moon, or hard moon, presumably). This is because they have fallen victim to a spell by Mrs. Chou (ちょう).', NULL),
  ('00000000-0000-4000-8000-000000002334', 'kanji', '槽', '槽', 57, 6, 'A tree melts into the ground after listening to loud music in the hot sun, so you have to find a nice big tank to scoop the melted tree into. The music made the tree vibrate at juuust the right frequency that it, combined with the hot sun, made the tree turn into a puddle. You can''t just leave it being all blobby on the ground, so you find a tank for it.', 'You''re staring at the big tank when an eerie sound comes out, "Oooh I am the soul (そう) of the tree! You''ve trapped me in this tank and now I''m going to haunt it!" You don''t want to be haunted by a tank with a soul stuck in it.', NULL),
  ('00000000-0000-4000-8000-000000002335', 'kanji', '伐', '伐', 57, 7, 'If the leader of your gang is a drunkard he''ll try to have you fell trees thinking they''re rival gang members. You all know they aren''t but you can''t argue with your leader, especially if he''s drunk. Go ahead and attack the trees anyway.', 'As you attack the innocent trees with your chains and sticks, a bunch of bats (ばつ) come flying out and attack YOU! You have your own kind of bats so now you''re all trying to fell the bats with YOUR bats!', NULL),
  ('00000000-0000-4000-8000-000000002336', 'kanji', '漬', '漬', 57, 8, 'Tsunamis get blamed because they pickle everything in their path. That means that everything smells of pickles after a tsunami.', 'Looking at all those pickles, you bend down and pick up two (つ) of them. One in each hand. You look at the pickles in your hand and wonder whether to try one.', NULL),
  ('00000000-0000-4000-8000-000000002337', 'kanji', '坪', '坪', 57, 9, 'The amount of dirt you need to get some peace is a two mat area. Two tatami mats, that is. This is a pretty common measurement in Japan, so you should get really familiar with the amount of space that two tatami mats take up together.', 'A two mat area also happens to be big enough to hold two bodies (つぼ). That''s enough space to bring peace to two living, or dead, bodies!', NULL),
  ('00000000-0000-4000-8000-000000002338', 'kanji', '紺', '紺', 57, 10, 'If you want to turn your thread into a sweet color you just HAVE to go with navy or dark blue. That''s the sweetest color in existence, everyone knows that. After all, blue raspberry flavor is dark blue and it''s super sweet.', 'Now that your threads are navy colored you need to be careful that condors (こん) don''t try to steal it for their nests. Condors love dark blue things and thread is perfect for a condor nest.', NULL),
  ('00000000-0000-4000-8000-000000002339', 'kanji', '羅', '羅', 57, 11, 'You have a net of thread for catching a turkey. But, it must be spread out and you must arrange it first.', 'You spread out your net and arrange it just so. You expect it to catch a turkey, but instead you catch the ancient Egyptian god Ra (ら).', NULL),
  ('00000000-0000-4000-8000-000000002340', 'kanji', '峡', '峡', 57, 12, 'To the mountains you took your horned husband for you two to get married. (Society wouldn''t accept a horned husband!) To hide even more from the prying eyes of society, you take your horned husband into a ravine.', 'The ravine is still in きょうと though, because if you went outside the city your marriage wouldn''t be legal. So you found a secluded, local ravine.', NULL),
  ('00000000-0000-4000-8000-000000002341', 'kanji', '俸', '俸', 57, 13, 'The leader says spring is looking dry, so you''ll need your salary in advance.', 'Your salary is sent straight to your home (ほう) instead of the bank. Okay, something is definitely fishy here.', NULL),
  ('00000000-0000-4000-8000-000000002342', 'kanji', '醸', '醸', 57, 14, 'An alcohol nurse is someone who nurses alcohol. In other words, they brew it.', 'A brew of alcohol is what Jourm (じょう) loves most after a long day.', NULL),
  ('00000000-0000-4000-8000-000000002343', 'kanji', '弔', '弔', 57, 15, 'You give a bow and a stick to your friend''s family. This is because your friend died, and he loved bows and sticks. You give this to his family, to give our condolences.', 'More than a condolence, you want to avenge your friend''s death. He was killed by Mrs. Chou (ちょう), and she broke his stick and bow, which is why you got the family a new set.', NULL),
  ('00000000-0000-4000-8000-000000002344', 'kanji', '乙', '乙', 57, 16, 'Your nose isn''t the first thing people see about your face, it''s the latter. They see your eyes THEN your nose, then your mouth, in order going down. Just label them A B and C and you''ll never forget!', 'If you don''t have any cereal you have to eat your B breakfast option. Oats (おつ). You don''t hate oats, but they''re definitely not your first choice.', NULL),
  ('00000000-0000-4000-8000-000000002345', 'kanji', '遍', '遍', 57, 17, 'Riding a scooter to the library is a universal experience. People young and old have all, at some point, taken a scooter to the library, picked up a book, used the internet, sat in the comfy chairs, then left via that same scooter.', 'Riding a scooter to the library is so universal, even hens (へん) do it.', NULL),
  ('00000000-0000-4000-8000-000000002346', 'kanji', '衡', '衡', 57, 18, 'You go to a big rice paddy and establish a prison right in the middle of it to restore the equilibrium of the area.', 'To restore equilibrium in these parts, you throw all the 耕ing こういち clones into the prison.', NULL),
  ('00000000-0000-4000-8000-000000002347', 'kanji', '款', '款', 60, 19, '"For the  samurai, it is a jackhammer that they will lack." That is the latest article of the law written about samurai, hundreds of years after katana were taken away. This article was written with great sincerity by the government.', 'The one who wrote these articles with such sincerity was Genghis Khan (かん).', NULL),
  ('00000000-0000-4000-8000-000000002348', 'kanji', '閲', '閲', 57, 20, 'Put a guard at your gate to get a good inspection of your neighborhood going. The guard will stand there all day inspecting everything and then report it all back to you. You won''t have to do any of the inspection yourself!', 'His inspection is complete, but it looks like he''s used an etch (えつ) a sketch to record all the results. That''s not really helpful. If you shake it all the inspection results will disappear!', NULL),
  ('00000000-0000-4000-8000-000000002349', 'kanji', '喝', '喝', 57, 21, 'If you put your spoon in the sun while you''re in prison, a mouth will appear to scold you. You can never see who the mouth belongs to, but considering you''re in prison it''s probably a guard. Either way, that person doesn''t like what you''re doing and they keep scolding you when you put your spoon out into the sun.', 'One day you finally get fed up. You need to know who the mouth of the person who''s scolding you is. You stick your spoon out into the sun and the mouth appears, scolding you right on time. You reach out and grab them. But in your hand is a pile of cats (かつ).', NULL),
  ('00000000-0000-4000-8000-000000002350', 'kanji', '敢', '敢', 57, 22, 'An elf who ventures outside in winter has a lot of daring. Elf ears are very, very delicate, and the winter cold can really mess them up. So if you see an elf adventuring in winter, know that that particular elf is a really daring dude.', 'The amount of daring you''d need is about equal to the amount Genghis Khan (かん) had. And he was really daring!', NULL),
  ('00000000-0000-4000-8000-000000002351', 'kanji', '膜', '膜', 57, 23, 'If you trap the moon in a greenhouse it will grow a creepy membrane around itself. The moon isn''t used to the heat it would be exposed to in a greenhouse so that membrane is there to protect it. It''s really gross looking though.', 'You decide to open the greenhouse to check this moon membrane out but when you open the door the smell of big macs (まく) hits you in the face. Eww. Why does this membrane smell like a big mac... or does that mean big macs smell like a festering moon?', NULL),
  ('00000000-0000-4000-8000-000000002352', 'kanji', '盲', '盲', 57, 24, 'The death of your eyes means that you''ve gone blind.', 'When you''re blind you probably shouldn''t drive anymore because if you do you''ll mow (もう) everyone over. Actually, don''t mow your lawn either. Blind people probably shouldn''t be driving anything.', NULL),
  ('00000000-0000-4000-8000-000000002353', 'kanji', '胎', '胎', 57, 25, 'The machine in your body that is powered by the moon is your womb, also called your uterus! Haven''t you ever wondered why periods happen with the revolutions of the moon? That''s because it powers your uterus and tells it what to do!', 'It kind of sucks, but there is no way to sever this uterus - moon tie (たい). But if you find a way please tell me, I can''t take this anymore.', NULL),
  ('00000000-0000-4000-8000-000000002354', 'kanji', '酵', '酵', 57, 26, 'Alcohol is a good teacher on the process of fermentation.', 'Using fermentation, you are indeed making some alcohol. It will be drunk at a party put on by Emperor こういち.', NULL),
  ('00000000-0000-4000-8000-000000002355', 'kanji', '堕', '堕', 57, 27, 'Even if you have a building, it will eventually turn back into dirt. Everything will degenerate eventually. A brick falls off here, a door comes loose there. Nothing can last forever.', 'As you watch the building degenerate, you can''t help but think of your dad (だ). You had to watch him waste away the same way of a degenerative disease. Why do people have to die, dad?', NULL),
  ('00000000-0000-4000-8000-000000002356', 'kanji', '遮', '遮', 57, 28, 'You''re riding your scooter toward your yurt as fast as you can because someone is trying to get in there to boil your water and you want to intercept them.', 'You manage to intercept the shaman (しゃ) who was just about to open the door to your yurt, and instead you crash right into him.', NULL),
  ('00000000-0000-4000-8000-000000002357', 'kanji', '烏', '烏', 57, 29, 'An altered bird is a crow! They look like birds but they''re bigger and darker and smarter!', 'If you can''t tell just from looking at it that it''s a crow and not a bird, walk up to it and caress (からす) it with your hand! If it caresses you back, it''s a crow! If it freaks out and flies away or pecks your face, it''s a normal bird. Crows are really smart and like affection. That''s what makes them so cool!', NULL),
  ('00000000-0000-4000-8000-000000002358', 'kanji', '凸', '凸', 57, 30, 'The convex radical and the convex kanji are the same, so hopefully you now just know them both.', 'Is this convex? It''s totes (とつ) convex!', NULL),
  ('00000000-0000-4000-8000-000000002359', 'kanji', '凹', '凹', 57, 31, 'The concave radical and the concave kanji are the same!', 'If you call someone concave the 王 (おう) will find out and he''ll have his guards turn you concave.', NULL),
  ('00000000-0000-4000-8000-000000002360', 'kanji', '楓', '楓', 57, 32, 'A tree that does well in the wind is a maple tree. Maple trees don''t have fruit so the wind can''t knock anything off of it. That''s why they thrive well in windy places!', 'When the wind goes through the maple tree you know it''s kite day (かえで)!', NULL),
  ('00000000-0000-4000-8000-000000002361', 'kanji', '哉', '哉', 57, 33, 'A drunkard has dirt in his mouth as he tries to talk to you. You walk over and he spits a question mark into your hand. It''s covered in dirt and spit. Um... does this mean he''s confused? He probably doesn''t even know where he is. But how did he make this question mark and why was it in his mouth?', 'The drunkard takes the question mark back and presses it to his head. He''s wearing a Yankee''s (や) cap. Oh come on. "Do you just want to know the Yankee''s score in the game?" The drunkard nods.', NULL),
  ('00000000-0000-4000-8000-000000002362', 'kanji', '蒼', '蒼', 57, 34, 'Flowers grown in a warehouse will be very pale. They never see the sun, so they don''t grow to have bright colors.', 'When you grow pale flowers like this, they don''t grow a soul (そう). Soul adds color to plants and flowers. That''s probably why ghosts and dead bodies are pale too.', NULL),
  ('00000000-0000-4000-8000-000000002363', 'kanji', '瑠', '瑠', 57, 35, 'The king will send his men with swords into your private rice paddy if you come across lapis lazuli. Even though this is your private land, he wants that lapis lazuli to make some new crowns and thrones for himself. Plus he''s the king, so he can do whatever he wants.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000007828', 'vocabulary', '苗', '苗', 51, 81, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Since this word is made up of a single kanji, it probably uses the kun''yomi reading. You did not learn this reading, so here''s a mnemonic to help you: 
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000008027', 'vocabulary', '脂身', '脂身', 53, 105, 'Lemak pada tubuh hewan disebut daging berlemak. Beberapa orang sangat suka memakannya dan yang lain sangat membencinya.', 'The readings for this word are both kun''yomi readings. You haven''t learned this reading for 脂 yet, so here''s a mnemonic to help you:
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000008227', 'vocabulary', '粗い', '粗い', 55, 86, 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari kasar? Kasar atau kasar.', 'Since this word consists of a kanji with hiragana attached, you can bet that it will use the kun''yomi reading. You didn''t learn this reading yet, so here''s a mnemonic to help you:
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000008427', 'vocabulary', '検閲', '検閲', 57, 123, 'Jika Anda memeriksa sesuatu terlalu dekat selama pemeriksaan, Anda mungkin akan menemukan cacat dan ingin menyensornya. Letakkan garis hitam kecil di atas semua kekurangan yang Anda temukan saat Anda menatap.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000008428', 'vocabulary', '校閲', '校閲', 57, 124, 'Inspeksi yang Anda lakukan terhadap pekerjaan rumah Anda sebelum sekolah adalah revisi. Terkadang mengoreksi akan membantu Anda menemukan kesalahan sebelum Anda menyerahkannya juga. Pastikan Anda memeriksa semuanya.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000008429', 'vocabulary', '鼓舞', '鼓舞', 57, 125, 'Iramanya membuat Anda ingin menari. Itu adalah inspirasi yang Anda butuhkan untuk menari. Iramanya memberi Anda dorongan untuk menari sepanjang malam. Dan tanpa hentakan yang begitu hebat, gerakan tarian Anda akan timpang.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000008430', 'vocabulary', '鼓', '鼓', 57, 126, 'Apa yang Anda pukul untuk membuat pukulan yang menyakitkan? Drum tangan kecil yang keren.', 'Since this word is made up of a single kanji, it probably uses the kun''yomi reading. You did not learn this reading, so here''s a mnemonic to help you: 
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000008629', 'vocabulary', '泌尿器', '泌尿器', 60, 76, 'Wadah tempat keluarnya urin Anda adalah organ kemih Anda.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000008630', 'vocabulary', '渓谷', '渓谷', 60, 77, 'Lembah di lembah tetaplah lembah!', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000008631', 'vocabulary', '渓流', '渓流', 60, 78, 'Aliran yang mengalir melalui lembah adalah aliran pegunungan. Lembah terdapat di antara gunung-gunung, jadi bayangkan saja sungai yang mengalir melalui tengah-tengahnya di kepala Anda.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000008632', 'vocabulary', '湧く', '湧く', 60, 79, 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya baik, jadi versi kata kerjanya adalah baik.', 'Since this word consists of a kanji with hiragana attached, you can bet that it will use the kun''yomi reading. You didn''t learn that reading with this kanji, so here''s a mnemonic to help you: 
